arguments.command:
python3 - <<'PY'
import re
from pathlib import Path
text=Path('/app/input.tex').read_text()
syn={}
for line in Path('/app/synonyms.txt').read_text().splitlines():
    parts=[x.strip() for x in line.split(',')]
    syn[parts[0].lower()]=parts
for n,line in enumerate(text.splitlines(),1):
    words=re.findall(r"[A-Za-z]+",line)
    hits=[]
    for w in words:
        if w.lower() in syn:
            opts=syn[w.lower()]
            hits.append(f"{w} -> {', '.join(opts[1:])}")
    if hits:
        print(f'{n}: ' + ' | '.join(hits))
PY

